style.css:
@-moz-document domain("wikipedia.org") {
/* ========= PALETA ========= */

:root{
    --px-bg:#2f2f2f;
    --px-panel:#4a4a4a;
    --px-light:#6b6b6b;
    --px-dark:#181818;
    --px-gold:#ffd34d;
    --px-blue:#66b8ff;
    --px-text:#f3f3f3;
}

/* ========= FUENTE ========= */

*{
    font-family:"Minecraft Ten","Press Start 2P","VT323",monospace !important;
    border-radius:0!important;
    text-shadow:none!important;
}

/* ========= FONDO ========= */

html,
body{
    background:var(--px-bg)!important;
    color:var(--px-text)!important;
}

/* ========= PANELES ========= */

.vector-header,
.vector-sidebar,
.vector-page-toolbar,
.vector-page-titlebar,
.mw-body,
#content,
.infobox,
.wikitable,
.thumbinner{

    background:var(--px-panel)!important;

    border:3px solid var(--px-dark)!important;

    box-shadow:
        inset 2px 2px var(--px-light),
        inset -2px -2px #111!important;
}

/* ========= TÍTULOS ========= */

h1,h2,h3,h4,h5,h6{

    color:var(--px-gold)!important;

    border-bottom:3px solid #666!important;

    letter-spacing:1px;
}

/* ========= TEXTO ========= */

p,
li,
td,
th{
    color:var(--px-text)!important;
}

/* ========= LINKS ========= */

a{
    color:var(--px-blue)!important;
    text-decoration:none!important;
}

a:hover{

    background:#555;

    color:#fff86d!important;
}

/* ========= TABLAS ========= */

.wikitable th{

    background:#707070!important;

}

.wikitable td{

    background:#555!important;

}

/* ========= INFOBOX ========= */

.infobox caption,
.infobox-title{

    background:#6b6b6b!important;

    color:white!important;

}

/* ========= BOTONES ========= */

button,
input,
select{

    background:#666!important;

    color:white!important;

    border:3px solid #222!important;

    border-top-color:#888!important;

    border-left-color:#888!important;

    border-bottom-color:#111!important;

    border-right-color:#111!important;
}

/* ========= BUSCADOR ========= */

input[type="search"]{

    background:#444!important;

}

/* ========= IMÁGENES ========= */

img{

    image-rendering:pixelated;

}

/* ========= SCROLL ========= */

::-webkit-scrollbar{

    width:16px;

}

::-webkit-scrollbar-track{

    background:#333;

}

::-webkit-scrollbar-thumb{

    background:#777;

    border:3px solid #222;

}

/* ========= TRANSICIONES ========= */

*{
    transition:none!important;
}
}
